import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"16、【豫】 坤下震上","description":"周易闡真 - 16、【豫】 坤下震上","frontmatter":{"title":"16、【豫】 坤下震上","description":"周易闡真 - 16、【豫】 坤下震上"},"headers":[],"relativePath":"classics/chanzhen/017.md","filePath":"classics/chanzhen/017.md"}'),s={name:"classics/chanzhen/017.md"};function n(c,a,i,o,l,h){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：豫，剛應而志行，順以動，豫。豫順以動，故天地如之，而況建侯行師乎？天地以順動，故日月不過，而四時不忒。聖人以順動，則刑罰清而民服，豫之時義大矣哉！</p></blockquote><h1 id="_16、【豫】-坤下震上" tabindex="-1">16、【豫】 坤下震上 <a class="header-anchor" href="#_16、【豫】-坤下震上" aria-label="Permalink to “16、【豫】 坤下震上”">​</a></h1><p>初六：鳴豫，兇。</p><p>六二：介於石，不終日，貞吉。</p><p>六三：盱豫。悔遲。有悔。</p><p>九四：由豫，大有得。勿疑。朋盍簪。</p><p>六五：貞疾，恆不死。</p><p>上六：冥豫。成有渝，無咎。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。</p><p>豫者，樂也。上震雷，下坤地，是雷出於地，奮發而升，陽氣通和，萬物無不為之爽暢，豫之象也。</p><p>先王有見於此，知德者，天之所命，為人生之根本，不可不樂於修為，以是作樂以崇其德焉。樂所以和德，德所以成樂。若不崇德而作樂，是謂苦中作樂。惟借樂以和德，其德愈崇；借德以作樂，其樂愈和。德樂相符，是謂真樂，其樂音之殷盛，足以薦上帝、配祖考。蓋上帝之所喜者德，祖考之所悅者亦德。薦上帝，以德薦也；配祖考，以德配也。作樂不失其德，是不違其上帝，不忘其祖考。不違上帝，答天也；不忘祖考，報本也。夫人之有生，命受於上帝，形本於祖考。形所以載命，命所以全形，形與命兩不相離。報本即是答天，答天即是報本。答天報本，神鬼皆樂，而人焉有不樂？崇德作樂之效有如此，人何樂而不崇德哉!</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>盱，音籲。盍，音合。簪，側林反。</p><p>豫者，樂也。卦德上震動，下坤順，順時而動，動而通順，故謂豫。此以陰招陽之卦，承上大有而來，大有健明兩用，富有日新之道也。富有日新，須要順時而動，方能成功。若能順時，則進健得正，用明得當，火候不差，爻銖有準，急緩得法，進退合節，由有為而至無為，自無得而復失之患。其順動之樂為何如?順動之象，莫如建侯行師，侯為一國之主，將為眾軍之主。建侯順天時，則一國治；行師順人心，則眾軍全。心為一身之主，如侯如將也。</p><p>順動利於建侯行師，即利於正心修身。順時而動，則利；不順時而動，則不利。利則得樂，不利則不樂。致樂之道，順而動之盡矣。</p><p>初六，居豫之初，又在三陰之下，性質本愚，且與小人為伍，自暴自棄，以苦為樂，是謂鳴豫。豫而至鳴，無樂而自為樂，終必入於下愚不移之地，而不得樂。此匪正取兇之樂也。</p><p>六二，無貪無求，樂天知命，如介於石，確然有守，不以外假而傷內真，至於非分之樂，不俟終日，則即去之。此守貞得吉之樂也。</p><p>六三，捨己之樂，仰望他人之樂，是謂盱豫。豫至於盱，未得於人，先失其己，致悔之道。既知盱人無益而速悔，則可無悔。否則，不能悔速，而悔遲，終必有悔，而不得樂。此失正致悔之樂也。</p><p>九四，以一陽而居於群陰之中，不為群陰所惑，且能點化群陰，皆來順之，是謂由豫大有得也。大得之象，如亂髮朋盍而歸於一簪，以一御紛，以定止亂，陽氣常振，陰氣自化，樂何如之。此用剛有得之樂也。</p><p>六五，柔而不剛，孤寂守靜，空而不實，如有疾而不能樂矣。然柔而得中，即不能致樂，亦不至招兇，雖有疾而恆不死，不死不活，獨守一貞，安於小乘，縱真陽在望，未許我有。此著於頑空無樂也。</p><p>上六，在豫之終，只知順行其樂，不知逆運其樂，是謂冥豫。豫至於冥，執固不通，順其所欲之樂，雖樂事已成，必有渝變，樂極生悲，終必自敗，與人無咎。此隨心所好失樂也。</p><p>然則樂之為道，總在能順；致樂之道，總在能順時而動。順時而動，陽氣舒暢，如雷出地外，奮發登天，震驚百里，一切邪魔魍魎，盡皆遁跡，生機不息，大地裡黃芽長遍，滿世界金花開綻，信步走去，頭頭是道，樂莫樂於此也。</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
